    private sealed class FakeApiClient : IApiClient
    {
        private readonly int _statusCode;
        private readonly string _contentType;
        private readonly string _body;

        public FakeApiClient(int statusCode, string contentType, string body)
        {
            _statusCode = statusCode;
            _contentType = contentType;
            _body = body;
        }

        public Task<PetstoreClient.ApiStreamResponse> SendStreamingAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body,
            Func<Task<Dictionary<string, string>>>? refreshHeaders,
            int? timeout,
            int? maxRetries,
            int? idleTimeout,
            CancellationToken cancellationToken
        )
        {
            return Task.FromResult(
                new PetstoreClient.ApiStreamResponse(
                    _statusCode,
                    new Dictionary<string, string> { { "content-type", _contentType } },
                    new MemoryStream(System.Text.Encoding.UTF8.GetBytes(_body))
                )
            );
        }

        public Task<PetstoreClient.ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            return Task.FromResult(
                new PetstoreClient.ApiHttpResponse(
                    _statusCode,
                    _body,
                    new Dictionary<string, string> { { "Content-Type", _contentType } }
                )
            );
        }
    }

    private sealed class UrlCapturingApiClient : IApiClient
    {
        public Uri? CapturedUrl { get; private set; }

        public Task<PetstoreClient.ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            CapturedUrl = url;
            return Task.FromResult(
                new PetstoreClient.ApiHttpResponse(
                    200,
                    "{\"name\":\"x\",\"photoUrls\":[]}",
                    new Dictionary<string, string> { { "Content-Type", "application/json" } }
                )
            );
        }
    }

    private sealed class QueryCapturingApiClient : IApiClient
    {
        public Uri? CapturedUrl { get; private set; }

        public Task<PetstoreClient.ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            CapturedUrl = url;
            // An empty JSON array satisfies the List<Pet> return type so the
            // convenience wrapper's deserialization and non-empty-body guard
            // both pass; the URL is captured before any response handling.
            return Task.FromResult(
                new PetstoreClient.ApiHttpResponse(
                    200,
                    "[]",
                    new Dictionary<string, string> { { "Content-Type", "application/json" } }
                )
            );
        }
    }

    private sealed class HeaderCapturingApiClient : IApiClient
    {
        public Dictionary<string, string> CapturedHeaders { get; private set; } = new();

        public Task<PetstoreClient.ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
            CapturedHeaders = new Dictionary<string, string>(headers);
            return Task.FromResult(
                new PetstoreClient.ApiHttpResponse(
                    200,
                    "{\"id\":1,\"name\":\"x\",\"photoUrls\":[]}",
                    new Dictionary<string, string> { { "Content-Type", "application/json" } }
                )
            );
        }
    }

