    private sealed class MultipartCapturingHandler : HttpMessageHandler
    {
        public string ContentType { get; private set; } = string.Empty;

        public string Body { get; private set; } = string.Empty;

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken
        )
        {
            ContentType = request.Content?.Headers.ContentType?.MediaType ?? string.Empty;
            Body = request.Content is null
                ? string.Empty
                : await request.Content.ReadAsStringAsync(cancellationToken);
            return new HttpResponseMessage(System.Net.HttpStatusCode.OK)
            {
                Content = new StringContent(
                    "{\"code\":200,\"type\":\"\",\"message\":\"success\"}",
                    System.Text.Encoding.UTF8,
                    "application/json"
                ),
            };
        }
    }

    private sealed class CapturingHandler : HttpMessageHandler
    {
        public string? Authorization { get; private set; }

        public List<string> HeaderNames { get; } = new();

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken
        )
        {
            Authorization = request.Headers.Authorization?.ToString();
            HeaderNames.AddRange(request.Headers.Select(header => header.Key));
            if (request.Content != null)
            {
                HeaderNames.AddRange(request.Content.Headers.Select(header => header.Key));
            }
            return Task.FromResult(
                new HttpResponseMessage(System.Net.HttpStatusCode.OK)
                {
                    Content = new StringContent(
                        "{\"id\":1,\"name\":\"x\",\"photoUrls\":[]}",
                        System.Text.Encoding.UTF8,
                        "application/json"
                    ),
                }
            );
        }
    }

