    [Fact]
    public async Task BhvSerialization109TestPathParamEncodedExactlyOnce()
    {
        // path-double-encoding regression: a string path param carrying an
        // encodable char (space, '/') must be percent-encoded exactly once.
        // The old api template wrapped the already-encoded SerializeStyled
        // output in a second EncodePathSegment, turning '%' into '%25' so a
        // space became '%2520' and '/' became '%252F'. tagName uses label
        // style, petId uses matrix style.
        var client = new UrlCapturingApiClient();
        var config = Configuration.Builder().BaseUrl("http://localhost").Build();
        var api = new PetApi(client, config);

        await api.GetPetTagAsync(7L, "a b/c", new GetPetTagOptions());

        // Use AbsoluteUri / PathAndQuery, which preserve percent-encoding in
        // the path (unlike ToString() which may unescape %20). A '%' is always
        // kept escaped, so the double-encoded "%25xx" artifacts survive
        // canonicalisation and are the reliable regression signal.
        string url = client.CapturedUrl!.AbsoluteUri;
        // '/' inside the value is always kept as %2F by .NET Uri.
        Assert.Contains("b%2Fc", url, StringComparison.Ordinal);
        // matrix style on petId -> ";petId=7".
        Assert.Contains(";petId=7", url, StringComparison.Ordinal);
        // The double-encoded artifacts (the old api-template bug) must NOT appear.
        Assert.DoesNotContain("%2520", url, StringComparison.Ordinal);
        Assert.DoesNotContain("%252F", url, StringComparison.Ordinal);
        Assert.DoesNotContain("%253D", url, StringComparison.Ordinal);
    }

    [Fact]
    public async Task BhvOperations068TestOptionalArrayQueryParamsSerializeStyledNotDebugBlob()
    {
        // optional-array-param parity (Wave D): getPetTag declares two OPTIONAL
        // array query params — `colors` (pipeDelimited, non-exploded) and
        // `sizes` (spaceDelimited, non-exploded). When the caller supplies
        // multiple values, each list must serialize through the per-element
        // stringify into its declared OAS style, NOT a language debug blob.
        // The cross-language bug (seen in the Go SDK) emitted the collection's
        // default debug representation instead of styled values; the .NET
        // analogue would be List<T>.ToString() leaking the type name
        // "System.Collections.Generic.List" into the query string. Assert the
        // real element values appear under the styled join and the debug blob
        // does not.
        var client = new UrlCapturingApiClient();
        var config = Configuration.Builder().BaseUrl("http://localhost").Build();
        var api = new PetApi(client, config);

        await api.GetPetTagAsync(
            7L,
            "tag",
            new GetPetTagOptions { Colors = ["blue", "black"], Sizes = ["S", "M"] }
        );

        string url = client.CapturedUrl!.AbsoluteUri;
        // pipeDelimited colors -> "blue|black"; the '|' is percent-encoded as
        // %7C by .NET Uri building. Both element values survive verbatim.
        Assert.Contains("colors=blue%7Cblack", url, StringComparison.Ordinal);
        // spaceDelimited sizes -> "S M"; the space is percent-encoded as %20.
        Assert.Contains("sizes=S%20M", url, StringComparison.Ordinal);
        // The individual element values must each be present in the query.
        Assert.Contains("blue", url, StringComparison.Ordinal);
        Assert.Contains("black", url, StringComparison.Ordinal);
        // The .NET collection debug blob (the cross-language Wave D bug) must
        // NOT appear: no leaked List type name, and no key with no value joined.
        Assert.DoesNotContain("System.Collections", url, StringComparison.Ordinal);
        Assert.DoesNotContain("List%601", url, StringComparison.Ordinal);
    }

