    private sealed class BodyCapturingApiClient : IApiClient
    {
        public object? CapturedBody { get; private set; }

        public Task<PetstoreClient.ApiHttpResponse> SendRequestAsync(
            string method,
            Uri url,
            Dictionary<string, string> headers,
            object? body
        )
        {
