    {
        string[] names =
        [
            "FindPetsByStatusAsync",
            "FindPetsByStatusWithHttpInfoAsync",
            "GetPetByIdAsync",
            "GetPetByIdWithHttpInfoAsync",
        ];

        foreach (string name in names)
        {
